Definition mt4 : Type := (Z * Z * Z * Z)%type.      (* [comment removed for export] *)
Definition sfmt_upd (cx cy i j e : Z) (acc : mt4) : mt4 :=
  let '(xp, yp, xn, yn) := acc in
  if e =? 1 then (Z.max xp (cx - j), Z.max yp (cy - i), Z.max xn (j - cx), Z.max yn (i - cy)) else acc.
Fixpoint sfmt_row (cx cy i j : Z) (row : list Z) (acc : mt4) : mt4 :=
  match row with [] => acc | e :: rest => sfmt_row cx cy i (j + 1) rest (sfmt_upd cx cy i j e acc) end.
Fixpoint sfmt_rows (cx cy i : Z) (rows : list (list Z)) (acc : mt4) : mt4 :=
  match rows with [] => acc | r :: rest => sfmt_rows cx cy (i + 1) rest (sfmt_row cx cy i 0 r acc) end.
(* [comment removed for export] *)
Definition bnd4 (acc : mt4) : Prop := let '(xp, yp, xn, yn) := acc in 0 <= xp <= 30 /\ 0 <= yp <= 30 /\ 0 <= xn <= 30 /\ 0 <= yn <= 30.

Definition fold4 (cx cy : Z) (hits : list (Z * Z)) (acc : mt4) : mt4 :=
  let '(xp, yp, xn, yn) := acc in
  (fold_left Z.max (map (fun ij => cx - snd ij) hits) xp, fold_left Z.max (map (fun ij => cy - fst ij) hits) yp,
   fold_left Z.max (map (fun ij => snd ij - cx) hits) xn, fold_left Z.max (map (fun ij => fst ij - cy) hits) yn).
Definition hits_row (i : Z) (n : nat) (row : list Z) : list (Z * Z) :=
  flat_map (fun jr : Z * Z => let '(j, e) := jr in if e =? 1 then [(i, j)] else []) (combine (map Z.of_nat (seq n (length row))) row).
Definition hits_rows (n : nat) (rows : list (list Z)) : list (Z * Z) :=
  flat_map (fun ir : Z * list Z => let '(i, row) := ir in hits_row i 0 row) (combine (map Z.of_nat (seq n (length rows))) rows).

