Definition sfmt_rowend (ra sp gp tp t0 t1 t2 s1 a0 a1 a4 a6 s2 s3 s4 s5 s6 s7 s8 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (xp yp xn yn : Z) : machine_state -> Prop :=
  fun ms' => exists (a3' a5' s9' s10' t5' t6' : word),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 xp) s1 a0 a1 (Z_to_bv 64 yp) a3' a4 a5' a6 (Z_to_bv 64 SHB) s2 s3 s4 s5 s6 s7 s8 s9' s10' s11
                  (Z_to_bv 64 yn) (Z_to_bv 64 xn) t5' t6')
             F (Z_to_bv 64 0x16e544) fc None m (seg_rom asegs).

(* [comment removed for export] *)
Ltac sf_norm := rewrite ?swrap32_mod64_small by lia; rewrite ?Z.add_0_r; rewrite ?Z.lxor_nilpotent.
(* [comment removed for export] *)
Ltac sf_forks STEP :=
  lwalk [0x16eb7c]; sf_norm;
  lazymatch goal with
  | |- evt _ _ (MS _ _ (Z_to_bv 64 0x16eb7c) _ _ _ _) => apply STEP; repeat (apply (f_equal2 pair)); lia
  | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) =>
      first [ br; sf_forks STEP
            | let H := fresh "CMP" in brfork H; rewrite ?signed_lit64 in H by lia; [sf_forks STEP | sf_forks STEP] ]
  end.

Lemma sfmt_elems : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s1 a0 a1 a3 a4 a5 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t5 t6 : word) F fc (m : mem)
    (rp sx cx cy i : Z) (row rest : list Z) (xp yp xn yn xp' yp' xn' yn' : Z),
  Z.of_nat k = sx - j -> 0 <= j -> (1 <= k)%nat -> 1 <= sx <= 30 -> 0 <= cx < sx -> 0 <= cy <= 30 -> 0 <= i <= 30 ->
  t5 = Z_to_bv 64 (sx - j) -> s9 = Z_to_bv 64 j -> a5 = Z_to_bv 64 (rp + 4 * j) -> s10 = Z_to_bv 64 (rp + 4 * j) -> a4 = Z_to_bv 64 rp ->
  s4 = Z_to_bv 64 cx -> s1 = Z_to_bv 64 cy -> s11 = Z_to_bv 64 (cy - i) -> ra = Z_to_bv 64 (i - cy) -> s5 = Z_to_bv 64 1 ->
  t0 = Z_to_bv 64 1 -> t1 = Z_to_bv 64 0 -> t2 = Z_to_bv 64 1 -> a6 = Z_to_bv 64 0 ->
  rest = skipn (Z.to_nat j) row -> Z.of_nat (length row) = sx -> small3 row ->
  sfmt_row cx cy i j rest (xp, yp, xn, yn) = (xp', yp', xn', yn') -> bnd4 (xp, yp, xn, yn) ->
  0 < rp -> rp mod 8 = 0 -> rp + 4 * sx <= 2^47 ->
  u32arr asegs m rp (map (Z_to_bv 64) row) -> acc asegs m rp (4 * sx) -> mem_inv asegs m ->
  evt asegs (sfmt_rowend ra sp gp tp t0 t1 t2 s1 a0 a1 a4 a6 s2 s3 s4 s5 s6 s7 s8 s11 F fc m xp' yp' xn' yn')
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 xp) s1 a0 a1 (Z_to_bv 64 yp) a3 a4 a5 a6 (Z_to_bv 64 SHB) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
             (Z_to_bv 64 yn) (Z_to_bv 64 xn) t5 t6)
        F (Z_to_bv 64 0x16e498) fc None m (seg_rom asegs)).
